"""OGC API Tiles provider that serves tiles generated by martin, in-process.

`martin-py` is a PyO3 binding onto Martin's own tile-serving code
(https://martin.maplibre.org/). This provider plugs it into the generic
tile provider (:mod:`app.provider.tiles`) as one more tile source, so
martin's tiles go out through pygeoapi's ``/collections/{id}/tiles``
routes with the tileset metadata, the TileJSON, the auth chain and the
HTTP caching every other tile collection gets.

Unlike the PMTiles provider, which serves tiles already cut, martin cuts
them on request: a GeoParquet dataset (local, or a bucket object, glob or
prefix) is tiled by martin's DuckDB tiler, a GeoJSON file by its GeoJSON
tiler. A PMTiles archive is served too, though ``PMTilesProvider`` reads
one through fastgeoapi's range cache and is the better fit.

Configuration::

    - type: tile
      name: app.provider.martin.MartinTilesProvider
      data: s3://fastgeoapi-demo/overture/transportation-lazio.parquet
      store_options: {region: auto, endpoint: fly.storage.tigris.dev}
      options:
        zoom: {min: 0, max: 14}
        schemes: [WebMercatorQuad]
        geometry_column: geometry      # GeoParquet only; default geom
        srid: 4326                     # GeoParquet only; default 4326
        layer_id: roads                # default: the file's stem
        worker_threads: 4              # martin's Tokio threads; default one per core
        cache_size_mb: 256             # martin's tile cache; 0 turns it off
      format: {name: pbf, mimetype: application/vnd.mapbox-vector-tile}

The translation from fastgeoapi's provider vocabulary to a martin config
works without martin-py installed: ``scripts/bench_tiles.py`` uses it to
write the config of a standalone martin server serving the same data.
"""

from __future__ import annotations

import dataclasses
import gzip
import os
import threading
from collections.abc import Mapping
from typing import Any, ClassVar, Literal
from urllib.parse import urlsplit

from pygeoapi.provider.base import ProviderGenericError
from pygeoapi.provider.tile import ProviderTileNotFoundError

from app.config.logging import create_logger
from app.provider.storage import is_remote
from app.provider.storage.factory import _for_obstore
from app.provider.tiles import TilesProvider
from app.tiles.contract import (
    VECTOR_MEDIA_TYPES,
    TileContent,
    TileOutsideError,
    TileSourceError,
    VectorLayer,
    data_type_for,
    format_parameter,
)
from app.tiles.sources import TileSourceContext

# Optional: the translation below (provider definition -> martin config) is
# used without it too (scripts/bench_tiles.py, test_martin_config.py), so a
# missing martin-py fails when a provider is built, not on import.
try:
    import martin_py
except ModuleNotFoundError as error:
    if error.name not in ("martin_py", "martin_py._core"):
        raise
    martin_py = None

logger = create_logger("app.provider.martin")

# part of the tiles' version: another martin may cut other tiles from the same data
MARTIN_VERSION = martin_py.__version__ if martin_py is not None else None

INLINE_INFLATE_LIMIT = 256 * 1024
"""Compressed bytes above which the async face inflates in a worker thread."""

_DEFAULT_LAYER_ID = "tiles"

# TileJSON 3.0.0's defaults, for what martin's TileJSON leaves out
_DEFAULT_MIN_ZOOM = 0
_DEFAULT_MAX_ZOOM = 30
_DEFAULT_BOUNDS = (-180.0, -85.05112877980659, 180.0, 85.05112877980659)


# -- martin configs from fastgeoapi's provider vocabulary ----------------------
# Pure translation, no I/O and no martin_py.

type MartinSourceKind = Literal["geojson", "pmtiles", "duckdb"]

DEFAULT_SRID = 4326
DEFAULT_GEOMETRY_COLUMN = "geom"
"""The GeoParquet provider's own default (``app.provider.geoparquet``)."""


def source_kind(data: str) -> MartinSourceKind | None:
    """The martin source kind that opens ``data``, recognised by its extension.

    A remote location naming no file (a bucket prefix, a glob) is read as
    a GeoParquet dataset, the only kind martin opens as a directory.

    Parameters
    ----------
    data : str
        A provider's ``data``: path, URL, bucket key, glob or prefix.

    Returns
    -------
    MartinSourceKind | None
        ``"geojson"``, ``"pmtiles"`` or ``"duckdb"``; None when martin-py
        has no source for it.
    """
    path = data.split("?", 1)[0].lower()
    if path.endswith((".geojson", ".json")):
        return "geojson"
    if path.endswith(".pmtiles"):
        return "pmtiles"
    if path.endswith((".parquet", ".geoparquet")) or "*" in path:
        return "duckdb"
    if "://" in path and not names_one_object(data):
        # a bucket prefix, with or without its trailing slash
        return "duckdb"
    return None


def names_one_object(data: str) -> bool:
    """Whether ``data`` names a single object, not a glob or a directory.

    Only a single object has a version of its own (an ETag, a size and
    modification time) a provider can follow. An object is told from a
    directory by the extension of its last segment: ``s3://b/theme=places``
    is a prefix, ``s3://b/places.parquet`` an object.
    """
    if data.endswith("/") or any(char in data for char in "*?["):
        return False
    return "." in data.rpartition("/")[2]


def geoparquet_location(data: str) -> str:
    """A remote directory as the glob martin's ``read_parquet`` needs.

    Martin hands a remote location straight to DuckDB's ``read_parquet``,
    which reads a trailing-slash URL as one object and gets a 404 for it,
    so a bucket prefix is expanded the way ``duckdb_.scan_expression``
    does for the native reader. A local path is left alone: martin only
    accepts an existing file there, never a directory or a glob.

    Parameters
    ----------
    data : str
        A GeoParquet provider's ``data``: file, glob or directory.

    Returns
    -------
    str
        The location to give martin as ``geoparquet``.
    """
    if "://" not in data or data.endswith((".parquet", ".geoparquet")) or "*" in data:
        return data
    return f"{data.rstrip('/')}/**/*.parquet"


def layer_id_from_data(data: str, fallback: str) -> str:
    """The data file's basename, without its extension, as layer id.

    ``s3://bucket/overture/transportation-lazio.parquet`` (or
    ``.geoparquet``, ``.geojson``, ``.pmtiles``) gives
    ``transportation-lazio``. A location naming no single file (a
    directory, a bucket prefix, a glob) gives ``fallback``.

    Parameters
    ----------
    data : str
        A provider's ``data``.
    fallback : str
        The id to use when the basename names nothing.

    Returns
    -------
    str
        The layer id to give martin.
    """
    basename = data.split("://", 1)[-1].rstrip("/").rpartition("/")[2]
    stem, dot, _ = basename.rpartition(".")
    if not dot or not stem or data.endswith("/") or any(char in stem for char in "*?["):
        return fallback
    return stem


def martin_store_options(store_options: dict | None, data: str) -> dict[str, Any]:
    """A provider's ``store_options`` as martin's per-source object-store keys.

    ``store_options`` are written in DuckDB's secret vocabulary; martin, like
    obstore, takes object_store's (``virtual_hosted_style_request``, an
    ``endpoint`` URL that, virtual-hosted, names the bucket) and turns them
    back into the DuckDB S3 secret it creates on each connection. So the
    translation the obstore reader already uses is reused here, ``scope``
    dropped included: martin's secret lives on the source's own connections
    and needs none. A plain ``http`` endpoint is refused by martin unless
    ``allow_http`` says so.

    Parameters
    ----------
    store_options : dict | None
        The provider's ``store_options``, if any.
    data : str
        The provider's ``data``, whose bucket a virtual-hosted endpoint names.

    Returns
    -------
    dict
        Keys to merge into the martin ``duckdb`` source entry; empty for a
        local file or a provider without ``store_options``.
    """
    if not store_options or "://" not in data:
        return {}
    options = _for_obstore(store_options, data)
    if str(options.get("endpoint", "")).startswith("http://"):
        options["allow_http"] = True
    return options


def duckdb_source(
    data: str,
    layer_id: str,
    *,
    geometry_column: str = DEFAULT_GEOMETRY_COLUMN,
    srid: int = DEFAULT_SRID,
    store_options: dict | None = None,
) -> dict[str, Any]:
    """One entry of martin's ``duckdb.sources`` list, for a GeoParquet dataset."""
    return {
        "geoparquet": geoparquet_location(data),
        "layer_id": layer_id,
        "geometry_column": geometry_column,
        "srid": srid,
        **martin_store_options(store_options, data),
    }


def martin_config_for_source(
    kind: MartinSourceKind,
    data: str,
    source_id: str,
    *,
    geometry_column: str = DEFAULT_GEOMETRY_COLUMN,
    srid: int = DEFAULT_SRID,
    store_options: dict | None = None,
    cache_size_mb: int | None = None,
) -> dict[str, Any]:
    """A martin config serving ``data`` as the one source ``source_id``.

    Parameters
    ----------
    kind : MartinSourceKind
        The martin source kind, see :func:`source_kind`.
    data : str
        The dataset location.
    source_id : str
        The source id, which is also the vector layer name in the tiles.
    geometry_column, srid, store_options
        For a ``duckdb`` source only.
    cache_size_mb : int | None
        martin's in-memory tile cache, in MB; None keeps martin's default,
        0 turns it off.

    Returns
    -------
    dict
        A config ``martin_py.TileServer.from_dict`` loads.
    """
    config: dict[str, Any]
    match kind:
        case "geojson":
            config = {"geojson": {"sources": {source_id: data}}}
        case "pmtiles":
            config = {"pmtiles": {"sources": {source_id: data}}}
        case "duckdb":
            source = duckdb_source(
                data,
                source_id,
                geometry_column=geometry_column,
                srid=srid,
                store_options=store_options,
            )
            config = {"duckdb": {"sources": [source]}}
    if cache_size_mb is not None:
        config["cache"] = {"size_mb": cache_size_mb}
    return config


# -- the tile source and the provider -------------------------------------------


@dataclasses.dataclass(frozen=True)
class MartinTilesConfig:
    """What the provider asks of martin: one source, and how martin runs it."""

    data: str
    kind: MartinSourceKind
    layer_id: str
    geometry_column: str = DEFAULT_GEOMETRY_COLUMN
    srid: int = DEFAULT_SRID
    worker_threads: int | None = None
    cache_size_mb: int | None = None
    store_options: dict[str, Any] | None = dataclasses.field(default=None, repr=False)

    def __post_init__(self) -> None:
        """Refuse values martin would refuse later, at the first tile."""
        if self.worker_threads is not None and self.worker_threads < 1:
            raise ProviderGenericError(user_msg="option worker_threads must be at least 1")
        if self.cache_size_mb is not None and self.cache_size_mb < 0:
            raise ProviderGenericError(user_msg="option cache_size_mb cannot be negative")
        if not self.layer_id.strip():
            raise ProviderGenericError(user_msg="option layer_id cannot be empty")

    @classmethod
    def from_context(cls, context: TileSourceContext) -> MartinTilesConfig:
        """Read the configuration from what the tile provider hands its source."""
        return cls.from_parts(context.data, context.options, context.store_options)

    @classmethod
    def from_provider_def(cls, provider_def: dict) -> MartinTilesConfig:
        """Read the configuration from a pygeoapi tile provider definition.

        The same reading the provider does, without building it: what
        ``scripts/bench_tiles.py`` uses to give a standalone martin server
        exactly the source the provider serves.
        """
        return cls.from_parts(
            provider_def["data"],
            provider_def.get("options") or {},
            provider_def.get("store_options"),
        )

    @classmethod
    def from_parts(
        cls, data: str, options: Mapping[str, Any], store_options: Mapping[str, Any] | None
    ) -> MartinTilesConfig:
        """Read the configuration from a provider's ``data``, ``options`` and ``store_options``."""
        kind = source_kind(data)
        if kind is None:
            raise ProviderGenericError(
                user_msg=(
                    f"martin cannot tile {data}: give a GeoParquet, GeoJSON or PMTiles location"
                )
            )
        try:
            return cls(
                data=data,
                kind=kind,
                layer_id=str(
                    options.get("layer_id") or layer_id_from_data(data, _DEFAULT_LAYER_ID)
                ),
                geometry_column=str(options.get("geometry_column", DEFAULT_GEOMETRY_COLUMN)),
                srid=int(options.get("srid", DEFAULT_SRID)),
                worker_threads=_optional_int(options.get("worker_threads")),
                cache_size_mb=_optional_int(options.get("cache_size_mb")),
                store_options=dict(store_options) if store_options else None,
            )
        except (TypeError, ValueError) as error:
            raise ProviderGenericError(user_msg=f"invalid martin option: {error}") from None

    def martin_config(self) -> dict[str, Any]:
        """The martin config of the one source; it may carry credentials."""
        return martin_config_for_source(
            self.kind,
            self.data,
            self.layer_id,
            geometry_column=self.geometry_column,
            srid=self.srid,
            store_options=self.store_options,
            cache_size_mb=self.cache_size_mb,
        )


def _optional_int(value: Any) -> int | None:
    return None if value is None else int(value)


@dataclasses.dataclass(frozen=True)
class _LoadedServer:
    """A martin ``TileServer`` and the version of the data it was loaded from.

    martin resolves a source once, when the server is built, so a server
    serves the data as it was then; ``data_version`` says which that was.
    """

    server: martin_py.TileServer
    source_id: str
    data_version: str | None


class MartinTiles:
    """The tiles martin cuts from one dataset: a tile source (:class:`TileSource`).

    The martin ``TileServer`` is built at the first read, not with the
    provider: pygeoapi builds every tile provider to write the OpenAPI
    document, and building a server resolves the source (opens the file,
    reads its schema). Concurrent first reads share one build.

    When the data is a single object whose version can be followed (a
    local file, or a remote object read with the range cache), a new
    version builds a new server, so tiles and their ETag always describe
    the same data. A glob, a prefix or a remote object without the range
    cache has no version: it is loaded once, and a change is seen after a
    restart or a config reload.
    """

    format = "martin"

    def __init__(self, context: TileSourceContext) -> None:
        """Check the configuration; no I/O."""
        if martin_py is None:
            raise ImportError(
                "the martin tile provider needs the 'martin' extra: uv sync --extra martin"
            )
        self._context = context
        self.config = MartinTilesConfig.from_context(context)
        self._follows_version = names_one_object(context.data)
        self._loaded: _LoadedServer | None = None
        self._loading = threading.Lock()

    # -- the data's version ------------------------------------------------------

    def data_version(self) -> str | None:
        """The version of the data, the same in every process; None when unknown."""
        if not self._follows_version:
            return None
        if not is_remote(self.config.data):
            return self._local_version()
        try:
            cached = self._context.cached()
            return None if cached is None else _object_version(cached.meta())
        except Exception as error:
            return self._stop_following_version(error)

    async def adata_version(self) -> str | None:
        """Async twin of :meth:`data_version`; the range cache answers without waiting."""
        if not self._follows_version:
            return None
        if not is_remote(self.config.data):
            # one stat: cheaper than a trip to a worker thread
            return self._local_version()
        try:
            cached = self._context.cached()
            if cached is None:
                return None
            return _object_version(await cached.ameta_without_waiting())
        except Exception as error:
            return self._stop_following_version(error)

    def _stop_following_version(self, error: Exception) -> None:
        """Serve without a version from now on, as for a glob, rather than fail every tile.

        The version only lets tiles follow a replaced object and carry an
        ETag: martin reads the data with its own reader, which may well
        work where the store asking the version does not (an option the
        store refuses, a HEAD the bucket forbids). Logged once.
        """
        self._follows_version = False
        logger.warning(
            f"martin serves {self.config.data} without following its version, which "
            f"cannot be read ({type(error).__name__}: {error}); a replaced object is "
            "seen after a restart"
        )

    def _local_version(self) -> str | None:
        path = urlsplit(self.config.data).path if "://" in self.config.data else self.config.data
        try:
            stat = os.stat(path)
        except OSError:
            # martin reports the missing file when it loads
            return None
        return f"{stat.st_size}:{stat.st_mtime_ns}"

    # -- the martin server ---------------------------------------------------------

    def _server_for(self, data_version: str | None) -> _LoadedServer:
        """The server loaded at ``data_version``, built again when the data has changed.

        Blocks while a server is built: call it from a worker thread on the
        async face.
        """
        loaded = self._loaded
        if loaded is not None and not self._is_stale(loaded, data_version):
            return loaded
        with self._loading:
            loaded = self._loaded
            if loaded is None or self._is_stale(loaded, data_version):
                loaded = self._loaded = self._load(data_version)
        return loaded

    @staticmethod
    def _is_stale(loaded: _LoadedServer, data_version: str | None) -> bool:
        # an unknown version keeps the server there is
        return data_version is not None and loaded.data_version != data_version

    def _load(self, data_version: str | None) -> _LoadedServer:
        try:
            server = martin_py.TileServer.from_dict(
                self.config.martin_config(), worker_threads=self.config.worker_threads
            )
        except martin_py.MartinError as error:
            # the detail may name storage or credentials: it goes to the log only
            logger.warning(f"martin could not load {self.config.data}: {error}")
            raise TileSourceError(f"martin could not load {self.config.data}") from None
        sources = server.list_sources()
        if len(sources) != 1:
            raise TileSourceError(
                f"martin resolved {len(sources)} sources from {self.config.data}, expected one"
            )
        logger.info(f"martin loaded {self.config.data} as {sources[0]!r} (version {data_version})")
        return _LoadedServer(server, sources[0], data_version)

    async def _aserver(self) -> _LoadedServer:
        data_version = await self.adata_version()
        loaded = self._loaded
        if loaded is not None and not self._is_stale(loaded, data_version):
            return loaded
        return await self._context.offload(self._server_for, data_version)

    # -- the tile source -------------------------------------------------------------

    def content(self) -> TileContent:
        """What martin says the source holds, from its TileJSON."""
        loaded = self._server_for(self.data_version())
        try:
            tilejson = loaded.server.tilejson(loaded.source_id)
            content_type = loaded.server.catalog()[loaded.source_id].get("content_type")
        except martin_py.MartinError as error:
            logger.warning(f"martin could not describe {self.config.data}: {error}")
            raise TileSourceError(f"martin could not describe {self.config.data}") from None
        return self._describe(tilejson, content_type)

    async def acontent(self) -> TileContent:
        """Async twin of :meth:`content`; the TileJSON is built in a worker thread."""
        return await self._context.offload(self.content)

    def tile(self, z: int, x: int, y: int) -> bytes | None:
        """The tile bytes, decompressed; None where the source has no data."""
        loaded = self._server_for(self.data_version())
        try:
            data, _, encoding = loaded.server.get_tile(loaded.source_id, z, x, y)
        except Exception as error:
            raise self._tile_error(error, z, x, y) from None
        return _inflate(data, encoding) if data else None

    async def atile(self, z: int, x: int, y: int) -> bytes | None:
        """The same tile, awaited: martin cuts it on its own runtime, off the event loop."""
        loaded = await self._aserver()
        try:
            data, _, encoding = await loaded.server.aget_tile(loaded.source_id, z, x, y)
        except Exception as error:
            raise self._tile_error(error, z, x, y) from None
        if not data:
            return None
        if encoding and len(data) > INLINE_INFLATE_LIMIT:
            return await self._context.offload(_inflate, data, encoding)
        return _inflate(data, encoding)

    def _tile_error(self, error: Exception, z: int, x: int, y: int) -> Exception:
        """The contract's error for what martin raised while cutting z/x/y.

        Who is at fault decides, as in martin's own HTTP server: the request
        (a zoom outside the source's, a coordinate outside the matrix) is a
        tile outside the data, 404; anything else is the source failing,
        500, with a generic message: the detail may name storage or
        credentials, and goes to the log instead. A source failure must not
        pass for a missing tile, or outages vanish from clients and error rates.
        """
        if isinstance(error, (martin_py.TileRequestError, ValueError)):
            return TileOutsideError(str(error))
        logger.error(
            f"martin could not cut tile {z}/{x}/{y} of {self.config.data}: "
            f"{type(error).__name__}: {error}"
        )
        return TileSourceError(f"martin could not cut tile {z}/{x}/{y}")

    def _describe(self, tilejson: dict[str, Any], content_type: str | None) -> TileContent:
        media_type = self._context.media_type or content_type or VECTOR_MEDIA_TYPES[0]
        low = int(tilejson.get("minzoom", _DEFAULT_MIN_ZOOM))
        high = int(tilejson.get("maxzoom", _DEFAULT_MAX_ZOOM))
        west, south, east, north = (float(i) for i in tilejson.get("bounds", _DEFAULT_BOUNDS))
        center = tilejson.get("center") or [(west + east) / 2, (south + north) / 2, low]
        return TileContent(
            data_type=data_type_for(media_type, self._context.dem),
            media_type=media_type,
            format_parameter=format_parameter(media_type),
            min_zoom=low,
            max_zoom=high,
            bounds=(west, south, east, north),
            center=(float(center[0]), float(center[1]), int(center[2] if len(center) > 2 else low)),
            name=tilejson.get("name"),
            description=tilejson.get("description"),
            attribution=tilejson.get("attribution"),
            layers=tuple(
                VectorLayer(
                    id=layer["id"],
                    description=layer.get("description"),
                    minzoom=layer.get("minzoom"),
                    maxzoom=layer.get("maxzoom"),
                    fields=layer.get("fields") or {},
                )
                for layer in tilejson.get("vector_layers", [])
                if "id" in layer
            ),
            tile_size=tilejson.get("tileSize"),
            dem=self._context.dem,
        )


def _object_version(meta: Any) -> str:
    """An object's ETag, or its size and modification time without one."""
    if meta.etag:
        return meta.etag
    modified = meta.last_modified.isoformat() if meta.last_modified is not None else ""
    return f"{meta.size}:{modified}"


def _inflate(data: bytes, encoding: str | None) -> bytes:
    """Tile bytes as the contract wants them: decompressed."""
    if not encoding or encoding == "identity":
        return data
    if encoding == "gzip":
        return gzip.decompress(data)
    raise TileSourceError(f"martin sent tiles encoded as {encoding}, which is not supported")


class MartinTilesProvider(TilesProvider):
    """Tiles cut by martin from a GeoParquet, GeoJSON or PMTiles dataset.

    See the module docstring for the configuration.
    """

    source_builder: ClassVar = MartinTiles
    source: MartinTiles

    def get_layer(self):
        """The layer name: the martin source id, which names the layer in the tiles too."""
        return self.source.config.layer_id

    async def aversion(self, layer=None, tileset=None, z=None, y=None, x=None, format_=None):
        """The version of the tile ``aget_tiles`` would answer.

        The data's, the definition's and martin's: another martin may cut
        other tiles from the same data. None when the data has no version
        to follow, and for a tile outside the limits, which answers 404
        whatever the version.
        """
        try:
            self._within_limits(z, x, y)
        except ProviderTileNotFoundError:
            return None
        data = await self.source.adata_version()
        if data is None:
            return None
        return f"{data}|{self.definition_digest()}|martin-{MARTIN_VERSION}"
